function luminance(hex) {
  const channels = hex
    .slice(1)
    .match(/../g)
    .map((part) => parseInt(part, 16) / 255)
    .map((value) =>
      value <= 0.04045 ? value / 12.92 : ((value + 0.055) / 1.055) ** 2.4,
    );
  return channels[0] * 0.2126 + channels[1] * 0.7152 + channels[2] * 0.0722;
}
const pairs = [
  ['ink', 'paper', 4.5],
  ['muted', 'paper', 4.5],
  ['primary', 'paper', 4.5],
  ['ink', 'surface', 4.5],
  ['muted', 'surface', 4.5],
  ['surface', 'primary', 4.5],
  ['primary', 'primarySoft', 4.5],
  ['secondary', 'secondarySoft', 4.5],
  ['danger', 'dangerSoft', 4.5],
  ['focus', 'paper', 3],
  ['focus', 'surface', 3],
  ['control', 'surface', 3],
  ['control', 'paper', 3],
];
const contrasts = pairs.map(([foreground, backgroundName, minimum]) => {
  const a = luminance(c[foreground]);
  const b = luminance(c[backgroundName]);
  const ratio = (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
  if (ratio < minimum)
    throw new Error(
      `${foreground}/${backgroundName}: ${ratio.toFixed(2)} < ${minimum}`,
    );
  return {
    foreground,
    background: backgroundName,
    ratio: Number(ratio.toFixed(2)),
    minimum,
  };
});
