const inputHash = digest(
  JSON.stringify(tokens) +
    (await readFile(fileURLToPath(import.meta.url), 'utf8')).replace(
      /\r\n/g,
      '\n',
    ),
);
const manifestPath = path.join(root, 'docs/brand/exports.json');
const binaryExports = [...output].filter(
  ([, value]) => typeof value !== 'string',
);
if (check) {
  const manifest = JSON.parse(await readFile(manifestPath, 'utf8'));
  if (manifest.inputHash !== inputHash)
    throw new Error('Raster inputs changed: run pnpm brand:export');
  for (const [name] of binaryExports) {
    if (digest(await readFile(path.join(root, name))) !== manifest.files[name])
      throw new Error(`Changed raster export: ${name}`);
  }
} else {
  emit(
    'docs/brand/exports.json',
    JSON.stringify(
      {
        inputHash,
        files: Object.fromEntries(
          binaryExports.map(([name, value]) => [name, digest(value)]),
        ),
      },
      null,
      2,
    ) + '\n',
  );
}

for (const [name, source] of output) {
  const content =
    typeof source === 'string'
      ? await prettier.format(source, {
          ...(await prettier.resolveConfig(path.join(root, name))),
          filepath: name,
          parser: name.endsWith('.svg') ? 'html' : undefined,
        })
      : source;
  const target = path.join(root, name);
  if (check) {
    const actual = await readFile(target);
    if (typeof content === 'string') {
      if (actual.toString('utf8').replace(/\r\n/g, '\n') !== content)
        throw new Error(`Stale generated file: ${name}`);
    } else {
      const expected = await sharp(content).metadata();
      const found = await sharp(actual).metadata();
      if (
        expected.width !== found.width ||
        expected.height !== found.height ||
        found.format !== 'png'
      )
        throw new Error(`Invalid PNG export: ${name}`);
    }
  } else {
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, content);
  }
}
